23	        <Box width="320px">
24	          <Story />
25	        </Box>
26	      </MemoryRouter>
27	    ),
28	  ],
29	};
30	export default meta;
31	
32	type Story = StoryObj<typeof ZimmProductCardContent>;
33	
34	/** Minimal, PLP-shaped default: name link, bag action, price — no attributes, no size chips. */
35	export const Default: Story = {
36	  args: {
37	    name: 'Natura Long Sleeve Linen Mini Dress',
38	    headingLevel: 'h3',
39	    href: '/product/123',
40	    currentPrice: '$595.00',
41	    showAttributes: false,
42	    showBag: true,
43	    onAddToBag: fn(),
44	    showSizeChips: false,
45	    showNotifyMe: false,
46	  },
47	};
48	
49	/** Wishlist-shaped: colour + size shown as plain text beneath the name. */
50	export const WithAttributes: Story = {
51	  args: {
52	    ...Default.args,
53	    showAttributes: true,
54	    colour: 'Ivory',
55	    size: 'M',
56	  },
57	};
58	
59	/**
60	 * Wraps `ZimmProductCardContent` so `selectedSizeChipValue` is genuinely live rather than a
61	 * static arg — neither this component nor the `ZimmSizeChipGroup` it composes tracks selection
62	 * itself (both are correctly controlled components), so a story that wants a chip click to
63	 * visually select must own that state itself, the same pattern
64	 * zimmProductCard/index.stories.tsx's `Default` story already uses via its own `DefaultExample`.
65	 * Unlike that file, `ZimmProductCardContentProps` is a single flat type, not a discriminated
66	 * union keyed by `variation` — `selectedSizeChipValue`/`onSizeChipSelect` are already valid
67	 * (optional) members on every value of the type, so `{...args, selectedSizeChipValue,
68	 * onSizeChipSelect}` needs no narrowing before it assigns back to `ZimmProductCardContentProps`,
69	 * unlike that other file's `propsWithLiveSelection`. `handleSizeChipSelect` still fires the
70	 * original `args.onSizeChipSelect` (the `fn()` spy below) so Storybook's Actions panel keeps
71	 * logging the click.
72	 */
73	const WithSizeChipsExample = (args: ZimmProductCardContentProps) => {
74	  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>('m');
75	  const handleSizeChipSelect = (value: string) => {
76	    setSelectedSizeChipValue(value);
77	    args.onSizeChipSelect?.(value);
78	  };
79	  return (
80	    <ZimmProductCardContent
81	      {...args}
82	      selectedSizeChipValue={selectedSizeChipValue}
83	      onSizeChipSelect={handleSizeChipSelect}
84	    />
85	  );
86	};
87	
88	/** PLP-shaped: the size-chip picker renders in place of the attributes line. Size chips are
89	 *  genuinely interactive here, not a static snapshot — starts pre-selected at 'M'; click a
90	 *  different chip to see the live selection move. Rendered via `WithSizeChipsExample` above,
91	 *  which owns `selectedSizeChipValue` as local state; every other arg below is unchanged. */
92	export const WithSizeChips: Story = {
93	  args: {
94	    ...Default.args,
95	    showSizeChips: true,
96	    sizeChipValues: SIZES,
97	    selectedSizeChipValue: 'm',
98	    onSizeChipSelect: fn(),
99	  },
100	  render: (args) => <WithSizeChipsExample {...args} />,
101	};
102	
103	/** Out-of-stock: the bag button is present but disabled, and the notify-me CTA takes its place
104	 *  as the available action. */
105	export const Unavailable: Story = {
106	  args: {
107	    ...Default.args,
108	    isUnavailable: true,
109	    showNotifyMe: true,
110	    onNotifyMe: fn(),
111	  },
112	};
113	
114	/** A variant re-fetch in progress — ZimmProductPrice renders its own invisible placeholder,
